import React, { useEffect } from "react";

export default function Toast({
  type,
  message,
  onClose
}) {
  useEffect(() => {
    const timer = setTimeout(onClose, 3500);

    return () => clearTimeout(timer);
  }, [onClose]);

  return (
    <div
      className={`toast ${type}`}
      role="status"
    >
      <span>{message}</span>

      <button
        type="button"
        onClick={onClose}
        aria-label="Dismiss notification"
      >
        ×
      </button>
    </div>
  );
}
